import{c as t,Q as r,j as o,m as n}from"./chunks/framework.BqPkuuVc.js";const c=JSON.parse('{"title":"Competitor Registry","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/competitor-registry.md","filePath":"user/reference/competitor-registry.md"}'),s={name:"user/reference/competitor-registry.md"};function a(i,e,d,h,l,g){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="competitor-registry" tabindex="-1">Competitor Registry <a class="header-anchor" href="#competitor-registry" aria-label="Permalink to &quot;Competitor Registry&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers maintaining a cross-event list of known competitors.</p><p>The <em>Competitor Registry</em> is meshO Manager&#39;s master list of the people who take part across your events — their names, clubs, card numbers, and Eventor/IOF identifiers. Once someone is in the registry they&#39;re recognised from one event to the next, so entering them again is a matter of picking their name rather than re-typing every detail.</p><p>It&#39;s one of the pages under <strong>Settings → Global registry</strong>, alongside the <a href="./club-registry">Club Registry</a> and the <a href="./../running-the-event/hire-items">Hire card registry</a>. Everything here is <strong>global</strong> — shared by every event on this server, and kept separate from any single event&#39;s competitor list.</p><h2 id="what-the-registry-does-for-you" tabindex="-1">What the registry does for you <a class="header-anchor" href="#what-the-registry-does-for-you" aria-label="Permalink to &quot;What the registry does for you&quot;">​</a></h2><ul><li><strong>Faster entry.</strong> When you add a competitor to an event, typing a name searches the registry; picking a match fills in their club, card number, and Eventor/IOF IDs for you. See <a href="./../event-setup/competitors-clubs-teams">Competitors, clubs and teams</a>.</li><li><strong>Recognising cards.</strong> When a card is downloaded that isn&#39;t entered in the current event, Manager looks the number up in the registry and shows the likely owner&#39;s name (in brackets) so you can add them in one click. See <a href="./../running-the-event/card-download">Downloading cards</a>.</li></ul><h2 id="open-the-competitor-registry" tabindex="-1">Open the Competitor Registry <a class="header-anchor" href="#open-the-competitor-registry" aria-label="Permalink to &quot;Open the Competitor Registry&quot;">​</a></h2><p>In <strong>Settings</strong>, under <strong>Global registry</strong>, choose <strong>Competitor registry</strong>. The count beside the search box shows how many people it holds.</p><h2 id="what-s-in-the-list" tabindex="-1">What&#39;s in the list <a class="header-anchor" href="#what-s-in-the-list" aria-label="Permalink to &quot;What&#39;s in the list&quot;">​</a></h2><p>Each row is one person, listed alphabetically by name, 50 to a page:</p><table tabindex="0"><thead><tr><th>Column</th><th>Notes</th></tr></thead><tbody><tr><td><strong>External ID</strong></td><td>The person&#39;s number in an entry system such as Eventor. Blank for someone you added by hand without one.</td></tr><tr><td><strong>Provider</strong></td><td>The system that number belongs to — usually <strong>Eventor</strong>. The same number can belong to two different people in two different systems, so the registry tells them apart by the pair.</td></tr><tr><td><strong>Name</strong></td><td>Click it to edit the person.</td></tr><tr><td><strong>Club</strong></td><td>Their club, drawn from the <a href="./club-registry">Club Registry</a>.</td></tr><tr><td><strong>Card number</strong></td><td>Their SportIdent or EMIT card number, if known.</td></tr><tr><td><strong>IOF ID</strong></td><td>The athlete&#39;s IOF Person ID, used by exports and re-imports.</td></tr></tbody></table><p>Your <a href="./settings#custom-fields">custom fields</a>, if you have any, follow as extra columns. Every column is shown to begin with: hide the ones you don&#39;t use from the column menu, drag a heading by its grip to reorder, and click a heading to sort. The layout is remembered on this computer.</p><p>Use <strong>Search competitors</strong> to filter by name, club, or card number.</p><blockquote><p><strong>Note:</strong> <a href="./../event-setup/competitors-clubs-teams#ranking">Rankings</a> are <strong>not</strong> kept here. They belong to one event, not to the person, because a ranking list is republished every few weeks — a place remembered from an event three months ago would be quietly out of date rather than obviously missing. Import the current list into each event that needs one; see <a href="./../event-setup/import-event-data#importing-rankings">Importing rankings</a>.</p></blockquote><h2 id="add-and-edit-people" tabindex="-1">Add and edit people <a class="header-anchor" href="#add-and-edit-people" aria-label="Permalink to &quot;Add and edit people&quot;">​</a></h2><p>From the <strong>Actions</strong> menu:</p><ul><li><strong>Add competitor…</strong> — a <strong>Surname</strong> is required; <strong>First name</strong>, <strong>Card number</strong>, <strong>IOF ID</strong>, <strong>Club</strong>, <strong>External ID</strong> and <strong>ID provider</strong> are optional, as are any custom fields. An External ID can&#39;t be one that another person already holds under the same provider.</li><li><strong>Clear competitor registry…</strong> — removes every person after you confirm, including people you added by hand and IOF IDs recorded only here. Events keep their own competitors. This can&#39;t be undone; with Eventor switched on, <strong>Refresh competitors from Eventor</strong> fills it again.</li></ul><p>Click a person&#39;s name to open <strong>Edit competitor</strong>, where you can change any of their details or delete them. To fill <strong>Card number</strong>, click into the field and insert the card into a connected reader. Changes here only reach events you create or enter people into afterwards — a competitor already in an event isn&#39;t changed, and deleting someone from the registry doesn&#39;t affect any event.</p><p>An event where cards are routinely borrowed can choose not to use the registry at all — see <a href="./../event-setup/low-key-events#ignore-competitor-registry">Ignore competitor registry</a>. The registry itself is untouched, and every other event goes on using it.</p><h2 id="keeping-it-up-to-date-with-eventor" tabindex="-1">Keeping it up to date with Eventor <a class="header-anchor" href="#keeping-it-up-to-date-with-eventor" aria-label="Permalink to &quot;Keeping it up to date with Eventor&quot;">​</a></h2><p>Today the registry is populated from <strong>Eventor</strong>. From the <strong>Actions</strong> menu, <strong>Refresh competitors from Eventor</strong> pulls the latest people for the <strong>Organisation ID</strong> in your Eventor settings and reports how many were loaded. The item only appears once <strong>Enable Eventor</strong> is switched on and the connection is set up under <strong>Settings → Eventor</strong> (see <a href="./settings#eventor">Settings</a>).</p><p>Manager also refreshes the registry by itself, in the background, after you import an event or its entries from Eventor — at most once a day.</p><blockquote><p><strong>What a refresh changes:</strong> it <strong>adds</strong> people who are new in Eventor and <strong>updates</strong> the details (name, club, card number) of people already in the registry — it never deletes. People you added by hand, and anyone Eventor no longer lists, are kept. Two things to know: a hand edit to an <em>Eventor</em> person&#39;s name, club, or card is overwritten on the next refresh (make lasting changes in Eventor itself), and your <strong>IOF ID</strong> and custom-field values are always preserved, because Eventor&#39;s export doesn&#39;t include them.</p></blockquote><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../event-setup/competitors-clubs-teams">Competitors, clubs and teams</a> — entering competitors into an event</li><li><a href="./club-registry">Club Registry</a> — the matching store for clubs</li><li><a href="./../event-setup/import-event-data">Importing event data</a></li><li><a href="./../event-setup/create-event-from-eventor">Creating an event from Eventor</a></li><li><a href="./../running-the-event/card-download">Downloading cards</a></li><li><a href="./settings">Settings</a></li><li><a href="./../event-setup/low-key-events">Low-key events</a> — an event that ignores the registry</li></ul>',25)])])}const m=t(s,[["render",a]]);export{c as __pageData,m as default};
